package com.mantou.salesdialer.contacts;
import java.util.*;import static com.mantou.salesdialer.contacts.PhoneIntakeModel.*;
public final class ContactListViewCheck {
 static int checks;static final String SLOT="a".repeat(32);static LocalDraftBinding.Snapshot c(int n,long rev,Qualification q,boolean refused){return LocalDraftBinding.snapshot(DataClass.FORMAT_FIXTURE,SLOT,"LOCAL-TARGET-"+String.format("%032x",n),rev,q,refused,"GENERATED_VIEW");}static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static void bad(Runnable r){try{r.run();throw new AssertionError("invalid view accepted");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args){var a=c(1,1,Qualification.CONFIRMED,false);var b=c(2,1,Qualification.CONFIRMED,false);var cc=c(3,2,Qualification.CONFIRMED,false);var d=c(4,1,Qualification.UNKNOWN,false);var e=c(5,2,Qualification.CONFIRMED,true);var input=List.of(a,b,cc,d,e);var preview=LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,input,List.of(LocalDraftBinding.create(b),LocalDraftBinding.create(c(3,1,Qualification.CONFIRMED,false))));Map<String,String> labels=new HashMap<>();for(int i=0;i<input.size();i++)labels.put(input.get(i).targetId,"199****"+String.format("%04d",i+1));
 var all=ContactListView.project(preview,labels,ContactListView.Filter.ALL,"",b.targetId);ok(all.total==5&&all.rows.size()==5,"all rows");ok(all.selectedId.equals(b.targetId),"visible selection preserved");for(var filter:ContactListView.Filter.values()){var p=ContactListView.project(preview,labels,filter,"",b.targetId);ok(p.rows.size()==(filter==ContactListView.Filter.ALL?5:1),"each status filtered "+filter);}
 var q=ContactListView.project(preview,labels,ContactListView.Filter.ALL," 0003 ",b.targetId);ok(q.rows.size()==1&&q.rows.get(0).targetId.equals(cc.targetId),"suffix search on display mask");ok(q.selectedId.isEmpty(),"hidden selection cleared without silently selecting another");ok(ContactListView.project(preview,labels,ContactListView.Filter.CREATE,"0003","").rows.isEmpty(),"query and status intersect");ok(ContactListView.project(preview,labels,ContactListView.Filter.ALL,"19900000003","").rows.isEmpty(),"no raw-number lookup");ok(ContactListView.project(preview,labels,ContactListView.Filter.ALL,"199****0003","").rows.size()==1,"display mask lookup");ok(ContactListView.project(preview,labels,ContactListView.Filter.ALL,".*","").rows.isEmpty(),"plain text not regex");labels.clear();ok(all.rows.size()==5&&all.rows.get(0).maskedNumber.equals("199****0001"),"immutable projection");try{all.rows.clear();throw new AssertionError("mutable result");}catch(UnsupportedOperationException expected){checks++;}
 bad(()->ContactListView.project(preview,Map.of(),ContactListView.Filter.ALL,"",""));bad(()->ContactListView.project(preview,Map.of(a.targetId,"19900000001"),ContactListView.Filter.ALL,"",""));bad(()->ContactListView.project(preview,Map.of(),null,"",""));bad(()->ContactListView.project(null,Map.of(),ContactListView.Filter.ALL,"",""));var empty=LocalDraftBatch.prepare(DataClass.FORMAT_FIXTURE,SLOT,List.of(),List.of());ok(ContactListView.project(empty,Map.of(),ContactListView.Filter.ALL,"",a.targetId).selectedId.isEmpty(),"empty clears stale selection");bad(()->ContactListView.project(empty,Map.of(),ContactListView.Filter.ALL,"x".repeat(65),""));System.out.println("ContactListViewCheck passed "+checks+" assertions");
 }
}
